sys_script_fix.script:
(function() {

    var vehicle = new GlideRecord('x_1947064_autoca_0_vehicle');
    vehicle.query();

    var total = 0;
    var matched = 0;
    var unmatched = 0;
    var alreadySet = 0;

    while (vehicle.next()) {

        total++;

        var ownerName = vehicle.getValue('owner_name');

        if (!ownerName) {
            unmatched++;
            gs.info('No owner name: ' + vehicle.getValue('vehicle_id'));
            continue;
        }

        var user = new GlideRecord('sys_user');
        user.addQuery('name', ownerName);
        user.setLimit(1);
        user.query();

        if (user.next()) {

            matched++;

            if (vehicle.getValue('owner') == user.getUniqueValue()) {
                alreadySet++;
            }

            gs.info(
                vehicle.getValue('vehicle_id') +
                ' | ' +
                ownerName +
                ' | User found: ' +
                user.getUniqueValue()
            );

        } else {

            unmatched++;

            gs.info(
                vehicle.getValue('vehicle_id') +
                ' | ' +
                ownerName +
                ' | USER NOT FOUND'
            );
        }
    }

    gs.info('========== OWNER TEST RESULT ==========');
    gs.info('TOTAL VEHICLES: ' + total);
    gs.info('MATCHED USERS: ' + matched);
    gs.info('UNMATCHED: ' + unmatched);
    gs.info('ALREADY SET: ' + alreadySet);

})();
